'use client';
import { Crown } from './crown';
import Link from 'next/link';
import { useState } from 'react';
import { business } from '@/lib/config';

const tabs = ['Overview', 'Birth charts', 'Bookings', 'Classes', 'Support', 'Settings'];
export function SpacePreview({ locale }: { locale: string }) {
  const [active, setActive] = useState('Overview');
  return <section className="space-preview"><div className="preview-banner"><span>YOUR SPACE · DESIGN PREVIEW</span><p>Sign in to the existing member site to access your personal information.</p><Link href={`/${locale}/sign-in`}>Sign in ↗</Link></div><div className="space-layout"><aside className="space-sidebar"><Crown className="space-emblem"/><p>A space to<br/><em>return to yourself.</em></p><nav aria-label="Member space preview">{tabs.map((tab,i) => <button key={tab} aria-current={active === tab ? 'page' : undefined} onClick={() => setActive(tab)}><span aria-hidden="true">{['⊙','☉','◷','◇','?','⚙'][i]}</span>{tab}<span className="sidebar-arrow">↗</span></button>)}</nav><Link href={`/${locale}`}>← Back to the website</Link></aside><div className="space-content"><div className="space-heading"><div><span className="eyebrow">YOUR PERSONAL SANCTUARY</span><h1>{active === 'Overview' ? 'Your next chapter starts within.' : active}</h1></div></div>
    {active === 'Overview' ? <><div className="dashboard-welcome"><div><span className="eyebrow">A MOMENT FOR YOU</span><h2>Pause. Listen.<br/><em>Find your own rhythm.</em></h2><Link className="pill primary" href={`/${locale}/sign-in`}>Continue your journey ↗</Link></div><div className="dashboard-orbits" aria-hidden="true"><i/><i/><i/><Crown/></div></div><div className="dashboard-grid"><button className="dashboard-card chart-tile" onClick={() => setActive('Birth charts')}><span className="eyebrow">SELF-KNOWLEDGE</span><h3>Your natal map</h3><p>Explore the patterns written in your birth chart.</p><span className="tile-link">Open your charts ↗</span></button><button className="dashboard-card" onClick={() => setActive('Bookings')}><span className="eyebrow">CONNECTION</span><h3>Your consultations</h3><p>Sign in to see your appointments and session details.</p><span className="tile-link">View your bookings ↗</span></button><button className="dashboard-card" onClick={() => setActive('Classes')}><span className="eyebrow">GROWTH</span><h3>Continue learning</h3><p>Return to your classes and deepen your practice.</p><span className="tile-link">Explore your learning ↗</span></button></div><div className="reflection-note"><Crown/><div><span className="eyebrow">A QUESTION TO CARRY</span><p>What becomes possible when you choose a different perspective?</p></div></div></> : <div className="space-empty"><span aria-hidden="true">{active === 'Birth charts' ? '☉' : active === 'Bookings' ? '◷' : '✧'}</span><h2>{active === 'Support' ? 'A little guidance, when you need it.' : active === 'Settings' ? 'Your details. Your preferences.' : `A home for your ${active.toLowerCase()}.`}</h2><p>{active === 'Support' ? 'Contact Mahla for help with your classes, appointments or account.' : 'This preview contains no personal account data. Sign in to the existing member site to continue.'}</p><Link className="pill primary" href={active === 'Support' ? `/${locale}/contact` : `/${locale}/sign-in`}>{active === 'Support' ? 'Contact Mahla' : 'Sign in to continue'} ↗</Link>{active === 'Classes' && <a className="text-link" href={business.classes}>Browse available classes</a>}{active === 'Bookings' && <Link className="text-link" href={`/${locale}/booking`}>Explore consultations</Link>}</div>}
    </div></div></section>;
}
